ST.xhtml:p:
dTemp4 := Axis_Z.NcToPlc.SetAcc;
IF bTorqueMonitor THEN
  IF nMotorDir = 0 THEN
    dTorqueTemp1 := dTorqueValue1;
    dTorqueTemp2 := dTorqueValue2;
    dAcc2Temp := -dZAxisAcc2;
    dTemp3 := dZAxisAcc1 - dAcc2Temp;
    IF dTemp3 = 0.0 THEN
      dTemp3 := 1.0;
    END_IF;
    dTemp1 := (dTorqueTemp1 - dTorqueTemp2)/dTemp3;
    dTemp2 := (dZAxisAcc1*dTorqueTemp2 - dAcc2Temp*dTorqueTemp1)/dTemp3;
    dMaxTorque := dTemp1*Axis_Z.NcToPlc.SetAcc + dTemp2;
    IF g_fiZAxisTorque > dMaxTorque AND Axis_Z.NcToPlc.SetAcc <= 0.0 THEN
      TorqueDelay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTorqueDelay)));
      IF TorqueDelay.Q THEN
        g_bZAxisTorqueWarn := TRUE;
      END_IF;
    ELSE
      TorqueDelay(IN := FALSE);
      g_bZAxisTorqueWarn := FALSE;
    END_IF;
  ELSIF nMotorDir = 1 THEN
    dTorqueTemp1 := -dTorqueValue1;
    dTorqueTemp2 := -dTorqueValue2;
    dAcc2Temp := -dZAxisAcc2;
    dTemp3 := dZAxisAcc1 - dAcc2Temp;
    IF dTemp3 = 0.0 THEN
      dTemp3 := 1.0;
    END_IF;
    dTemp1 := (dTorqueTemp1 - dTorqueTemp2)/dTemp3;
    dTemp2 := (dZAxisAcc1*dTorqueTemp2 - dAcc2Temp*dTorqueTemp1)/dTemp3;
    dMaxTorque := dTemp1*Axis_Z.NcToPlc.SetAcc + dTemp2;
    IF g_fiZAxisTorque < dMaxTorque AND Axis_Z.NcToPlc.SetAcc <= 0.0 THEN
      TorqueDelay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTorqueDelay)));
      IF TorqueDelay.Q THEN
        g_bZAxisTorqueWarn := TRUE;
      END_IF;
    ELSE
      TorqueDelay(IN := FALSE);
      g_bZAxisTorqueWarn := FALSE;
    END_IF;
  ELSE
    TorqueDelay(IN := FALSE);
    g_bZAxisTorqueWarn := FALSE;
  END_IF;
ELSE
  TorqueDelay(IN := FALSE);
  g_bZAxisTorqueWarn := FALSE;
END_IF;

IF g_bTouchPanel THEN
  IF g_nPlcState = 0 AND Axis_Z.NCTOPLC.AXISSTATE = 9 THEN
    bTouchPanelLift := TRUE;
  END_IF;
ELSE
  bTouchPanelLift := FALSE;
END_IF;

IF g_bZAxisTorqueWarn OR bTouchPanelLift THEN
  g_bZIdleWarnLift := TRUE;
ELSE
  g_bZIdleWarnLift := FALSE;
END_IF;
